def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    # Early prober forgiveness (e.g., Slot 5)
    if n >= 2 and history[0] == ('C', 'C') and history[1] == ('C', 'D'):
        if n >= 3 and history[2] == ('C', 'D'):
            pass
        else:
            return 'C'

    # Exploiter (e.g., Slot 2): first 4 rounds CC, round 5 they defect
    if n >= 5 and history[0] == ('C', 'C') and history[1] == ('C', 'C') and history[2] == ('C', 'C') and history[3] == ('C', 'C') and history[4] == ('C', 'D'):
        if (n - 5) % 4 == 0:
            return 'D'
        else:
            return 'C'

    # Parent's TFT with forgiveness
    last_opponent_move = history[-1][1]
    if last_opponent_move == 'C':
        return 'C'
    else:
        consecutive_defections = 0
        for i in range(n - 1, -1, -1):
            if history[i][1] == 'D':
                consecutive_defections += 1
            else:
                break
        if consecutive_defections >= 3:
            if rng.random() < 0.1:
                return 'C'
        elif consecutive_defections == 2:
            if rng.random() < 0.2:
                return 'C'
        return 'D'
